package com.himeros.interaction;
import com.himeros.identity.IdentityLookup;import com.himeros.shared.*;import com.himeros.shared.outbox.OutboxService;import java.util.*;import org.springframework.context.ApplicationEventPublisher;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class InteractionService implements InteractionQuery {private final InteractionRepository repo;private final IdentityLookup identity;private final ApplicationEventPublisher events;private final OutboxService outbox;public InteractionService(InteractionRepository repo,IdentityLookup identity,ApplicationEventPublisher events,OutboxService outbox){this.repo=repo;this.identity=identity;this.events=events;this.outbox=outbox;}
 @Transactional public Result interact(UUID actor,UUID target,String rawType){if(actor.equals(target))throw new IllegalArgumentException("Cannot interact with yourself");if(!identity.exists(target))throw new ResourceNotFoundException("Target user not found");Interaction.Type type=Interaction.Type.valueOf(rawType.toUpperCase());Interaction i=repo.findByActorIdAndTargetId(actor,target).orElseGet(()->new Interaction(actor,target,type));i.change(type);repo.save(i);boolean mutual=false;if(type==Interaction.Type.LIKE||type==Interaction.Type.SUPER_LIKE){mutual=repo.existsByActorIdAndTargetIdAndTypeIn(target,actor,List.of(Interaction.Type.LIKE,Interaction.Type.SUPER_LIKE));if(mutual)events.publishEvent(new MutualLikeDetected(actor,target));}outbox.append("Interaction",actor+":"+target,"himeros.interaction.created.v1","himeros.interaction.events.v1",actor,Map.of("actorId",actor,"targetId",target,"type",type.name(),"mutual",mutual));return new Result(type.name(),mutual);}
 @Override @Transactional(readOnly=true) public boolean hasSeen(UUID actor,UUID target){return repo.findByActorIdAndTargetId(actor,target).isPresent();}@Override @Transactional(readOnly=true) public Set<UUID> seenBy(UUID actor){return repo.targets(actor);}public record Result(String type,boolean mutualLike){}
}
